from itertools import product, combinations

def subsets(d):
    out=[]
    for r in range(len(d)+1):
        for c in combinations(d,r):
            out.append(frozenset(c))
    return out

D=[0,1,2]
premise = lambda C,L,S: any(x in C and x not in L for x in D)          # Some C are not L
concl   = lambda C,L,S: any(x in S and x not in L for x in D)          # Some S are not L

opts = {
 'A': lambda C,L,S,W: any(x in C and x in L for x in D),               # Some C like chili
 'B': lambda C,L,S,W: any(x in L and x in S for x in D),               # Some chili-lovers are S
 'C': lambda C,L,S,W: all((x not in C) or (x in S) for x in D),        # All C are S
 'D': lambda C,L,S,W: any(x in C and x not in L and x not in W for x in D), # Some C like neither
}

models=[(set(C),set(L),set(S),set(W)) for C in subsets(D) for L in subsets(D) for S in subsets(D) for W in subsets(D)]
print("num models:", len(models))

for k,f in opts.items():
    counter=[]
    for (C,L,S,W) in models:
        if premise(C,L,S) and f(C,L,S,W) and not concl(C,L,S):
            counter.append((sorted(C),sorted(L),sorted(S),sorted(W)))
    print(k, "valid?" , len(counter)==0, "| counterexamples:", len(counter), counter[:3])
