{"operation":"run_python","code":"from itertools import product

def check(n):
    results = {'A':True,'B':True,'C':True,'D':True}
    countermodels = {k:None for k in results}
    dom = list(range(n))
    # all subsets for CS and CG
    for CS_mask, CG_mask in product(range(1<<n), repeat=2):
        CS = [ (CS_mask>>i)&1 for i in dom ]
        CG = [ (CG_mask>>i)&1 for i in dom ]
        # premise: exists x with CS and not CG
        premise = any(CS[i] and not CG[i] for i in dom)
        if not premise: continue
        A = any(CG[i] and not CS[i] for i in dom)          # not all grads are CS / some grad not CS
        B = any(CS[i] and not CG[i] for i in dom)          # not all CS are grads
        C = any(CG[i] and not CS[i] for i in dom)          # some grad not CS
        D = any(CS[i] and CG[i] for i in dom)              # some CS is grad
        for k,v in zip('ABCD',[A,B,C,D]):
            if not v:
                results[k]=False
                if countermodels[k] is None:
                    countermodels[k]=(CS,CG)
    return results, countermodels

for n in (1,2,3):
    res, cm = check(n)
    print("domain size",n,"entailed options:",[k for k in 'ABCD' if res[k]])
    print("   countermodel for A (CS,CG):",cm['A'])
    print("   countermodel for D (CS,CG):",cm['D'])
