# Domain of size 2: individuals 0,1
# Predicates: Watt(x), Inv(x)=invented steam engine, Am(x)=American
# Premise P: exactly one x with Watt&Inv, and that x is not American.
def premise(W, Inv, Am):
    wits = [x for x in range(2) if W[x] and Inv[x]]
    return len(wits) == 1 and not Am[wits[0]]

models = []
for W in product([0,1], repeat=2):
    for Inv in product([0,1], repeat=2):
        for Am in product([0,1], repeat=2):
            if premise(list(W), list(Inv), list(Am)):
                models.append((W, Inv, Am))

print("number of models of premise:", len(models))

def A_opt(W,Inv,Am):
    wits=[x for x in range(2) if W[x] and Inv[x]]
    return all(not Am[x] for x in wits)   # "Watt (the steam-engine one) is not American"

def D_opt(W,Inv,Am):
    wits=[x for x in range(2) if W[x] and Inv[x]]
    return all(Inv[x] for x in wits)      # invented something -> is an inventor

def C_opt(W,Inv,Am):
    wits=[x for x in range(2) if W[x] and Inv[x]]
    # "it was the inventor who invented the steam engine": the described person is an inventor and did invent it
    return all(Inv[x] for x in wits)

def B_opt(W,Inv,Am):
    # some inventor is American: exists x with Inv(x) and Am(x)
    return any(Inv[x] and Am[x] for x in range(2))

for name, f in [("A",A_opt),("B",B_opt),("C",C_opt),("D",D_opt)]:
    vals = [f(*m) for m in models]
    print(name, "true in all models (entailed)?", all(vals), " true in", sum(vals), "of", len(vals))

# show a countermodel for B if it exists
for m in models:
    if not B_opt(*m):
        print("countermodel to B (domain 0,1): Watt,Inv,American =", m)
        break
