# Text's claim: reducing risk requires joint action S and C and O (necessary conditions).
# Model text as: R only if (S and C and O)  ==  R -> (S and C and O)
def text_holds(S,C,O,R):
    return (not R) or (S and C and O)
# D's claim: C alone is sufficient and guarantees R  ==  C -> R
def D_claim(S,C,O,R):
    return (not C) or R

# Find a valuation consistent with the text that makes D false
counter=[]
for S,C,O,R in itertools.product([False,True],repeat=4):
    if text_holds(S,C,O,R) and not D_claim(S,C,O,R):
        counter.append((S,C,O,R))
print("valuations where text is true but D is false:", counter)

# Also: text omits legal-help/cooperation from D's antecedent
print("D's antecedent mentions only community nursing+counselling; text also requires legal help (C) and crisis-org cooperation (O).")
