liquids = ['beer','cola','coffee']

def models(permissive=True):
    """Yield assignments of contents to 4 cups."""
    if permissive:
        # each cup: subset of liquids (2^3 = 8 options per cup)
        subsets = [set()]+[ {l} for l in liquids ]+[ {a,b} for i,a in enumerate(liquids) for b in liquids[i+1:] ]+[set(liquids)]
        for combo in product(subsets, repeat=4):
            yield combo
    else:
        # each cup: exactly one liquid, or empty
        opts = [None]+liquids
        for combo in product(opts, repeat=4):
            yield [set() if c is None else {c} for c in combo]

def evaluate(cups):
    beer = [ 'beer' in c for c in cups ]
    S1 = all(beer)
    S2 = 'cola' in cups[1]
    S3 = 'coffee' not in cups[2]
    S4 = any(not b for b in beer)
    return [S1,S2,S3,S4]

for permissive in (True, False):
    valid = []
    for cups in models(permissive):
        S = evaluate(cups)
        if sum(S) == 1:
            valid.append(cups)
    print("permissive =", permissive, " number of consistent models:", len(valid))
    # check each option: entailed?
    def A(cups): return all('beer' in c for c in cups)
    def B(cups): return all('cola' not in c for c in cups)
    def C(cups): return 'coffee' in cups[2]
    def D(cups): return 'cola' in cups[1]
    for name,f in [('A',A),('B',B),('C',C),('D',D)]:
        vals = [f(c) for c in valid]
        print("  option",name,": true in",sum(vals),"of",len(vals),"models ->", "ENTAILED" if all(vals) else ("REFUTED in some" if any(vals) else "always false"))
    # which statements are true in the models
    from collections import Counter
    print("  true-statement patterns:", Counter(tuple(evaluate(c)) for c in valid))
    print()
"}
